query:
SELECT (
    EXISTS(
        SELECT 1 FROM computations
        WHERE output_handle = $1
          AND transaction_id IS DISTINCT FROM $2
    )
    OR (
        NOT EXISTS(
            SELECT 1 FROM computations WHERE output_handle = $1
        )
        AND EXISTS(
            SELECT 1 FROM ciphertexts WHERE handle = $1
        )
    )
) AS "conflicts!"
